from collections import Counter
from statistics import median

def _lines_from_modes(values, fill, min_ratio=0.60):
    n = len(values)
    ans = []
    for i in range(n):
        cnt = Counter(values[i])
        color, amount = cnt.most_common(1)[0]
        if color != fill and amount / len(values[i]) >= min_ratio:
            ans.append(i)
    if len(ans) >= 2:
        gaps = [b-a for a,b in zip(ans, ans[1:])]
        pitch = int(median(gaps))
        if pitch > 1:
            while ans[0] - pitch >= 0:
                ans.insert(0, ans[0]-pitch)
            while ans[-1] + pitch < n:
                ans.append(ans[-1]+pitch)
    return ans

def transform(grid):
    h, w = len(grid), len(grid[0])
    freq = Counter(v for row in grid for v in row)
    fill = freq.most_common(1)[0][0]
    rows = _lines_from_modes(grid, fill)
    cols = _lines_from_modes([[grid[r][c] for r in range(h)] for c in range(w)], fill)
    if len(rows) < 2 or len(cols) < 2:
        return [row[:] for row in grid]
    out=[]
    for r0,r1 in zip(rows, rows[1:]):
        line=[]
        for c0,c1 in zip(cols, cols[1:]):
            corners=[grid[r0][c0],grid[r0][c1],grid[r1][c0],grid[r1][c1]]
            line.append(corners[0] if corners[0] != fill and corners.count(corners[0]) == 4 else fill)
        out.append(line)
    while out and all(v == fill for v in out[0]): out.pop(0)
    while out and all(v == fill for v in out[-1]): out.pop()
    while out and all(row[0] == fill for row in out):
        for row in out: row.pop(0)
    while out and all(row[-1] == fill for row in out):
        for row in out: row.pop()
    return out

