    # Grid rails are the rows and columns dominated by non-background cells.
    rr=[r for r,row in enumerate(grid) if sum(v==bg for v in row) < w/2]
    cc=[c for c in range(w) if sum(grid[r][c]==bg for r in range(h)) < h/2]
