    for r0,r1 in zip(rr,rr[1:]):
        row=[]
        for c0,c1 in zip(cc,cc[1:]):
            v=grid[r0][c0]
            row.append(v if v!=bg and v!=0 and grid[r0][c1]==v and grid[r1][c0]==v and grid[r1][c1]==v else bg)
        out.append(row)
    while out and all(v==bg for v in out[0]): out.pop(0)
    while out and all(v==bg for v in out[-1]): out.pop()
